package comtrya

// Allowed front-matter property types per doc. Users declare which
// fields each type carries; values in the MDX file's YAML front-matter
// must validate against this shape. Every doc auto-carries `body`
// (the MDX body); that field is reserved and need not be declared.
//
// Author / owner / reviewer-style fields take the kernel's typed
// #PrincipalRef family (#UserRef, #AgentRef, #BotRef, #CredentialRef).
// Declare them in CUE as `author: #UserRef & { slug: "rawkode" }` and
// the kernel will emit `{ slug, ref: "comtrya://user/rawkode" }`.
#DocPropertyType:
  string |
  int |
  bool |
  #PrincipalRef |
  [...string] |
  [...#PrincipalRef]

#DocProperties: {
  [string]: #DocPropertyType
}

// One doc type. The repo declares many; the slug is the directory
// under the Project root where files of this type live.
#DocType: {
  slug:        string
  label?:      string
  description?: string
  properties?: #DocProperties
}

// Add `docs` to every #Project, keyed by user-chosen type name
// ("adr", "rfc", "prd", "runbook", "playbook", ...).
#Project: {
  docs?: [string]: #DocType
}
